package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.util.*;
/** Independent small permutation enumeration, mechanism removal and exact variant recovery. */
public final class R26FamilyMechanismTest {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static final class Enumerated {double z;final double[][] p;final double[][][] edge;Enumerated(int n){p=new double[n][n];edge=new double[n-1][n][n];}}
    static void enumerate(double[][] s,double[][][] e,int[] order,int[] draw,int at,int used,Enumerated r){
        if(at<draw.length){for(int v=0;v<draw.length;v++)if((used&(1<<v))==0){draw[at]=v;enumerate(s,e,order,draw,at+1,used|1<<v,r);}return;}
        double energy=0;for(int pos=0;pos<draw.length;pos++)energy+=s[pos][draw[pos]];for(int k=0;k<order.length-1;k++)energy+=e[k][draw[order[k]]][draw[order[k+1]]];double mass=Math.exp(energy);r.z+=mass;for(int pos=0;pos<draw.length;pos++)r.p[pos][draw[pos]]+=mass;for(int k=0;k<order.length-1;k++)r.edge[k][draw[order[k]]][draw[order[k+1]]]+=mass;
    }
    static int[] permutation(int n,Random random){int[] d=new int[n];for(int i=0;i<n;i++)d[i]=i+1;for(int i=n-1;i>0;i--){int j=random.nextInt(i+1),v=d[i];d[i]=d[j];d[j]=v;}return d;}
    static byte[] save(OnlineModelsSU2.Model m)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
    static double loss(OnlineModelsSU2.Model m,int[] d){float[][] p=new float[10][10];m.predict(p,new float[m.stateWidth()]);double nll=0;for(int i=0;i<10;i++)nll-=Math.log(Math.max(1e-12,p[i][d[i]-1]));return nll/10;}
    public static void main(String[] args)throws Exception{
        Random random=new Random(260102);
        for(int n=3;n<=5;n++)for(int trial=0;trial<6;trial++){
            double[][] scores=new double[n][n];double[][][] pair=new double[n-1][n][n];for(double[] row:scores)for(int j=0;j<n;j++)row[j]=random.nextDouble()*2-1;for(double[][] edge:pair)for(double[] row:edge)for(int j=0;j<n;j++)row[j]=trial==0?0:random.nextDouble()-0.5;int[] order=permutation(n,random);for(int i=0;i<n;i++)order[i]--;
            Enumerated exact=new Enumerated(n);enumerate(scores,pair,order,new int[n],0,0,exact);PermutationChainR26.Result actual=PermutationChainR26.infer(scores,pair,order);check(Math.abs(actual.z-Math.log(exact.z))<1e-10,"chain partition differs from all permutations");
            for(int p=0;p<n;p++)for(int v=0;v<n;v++)check(Math.abs(actual.p[p][v]-exact.p[p][v]/exact.z)<1e-10,"chain unary marginal");for(int k=0;k<n-1;k++)for(int a=0;a<n;a++)for(int b=0;b<n;b++)check(Math.abs(actual.edge[k][a][b]-exact.edge[k][a][b]/exact.z)<1e-10,"chain edge marginal");
            if(trial==0){ExactPermutationR26.Result unary=ExactPermutationR26.infer(scores,null);for(int p=0;p<n;p++)for(int v=0;v<n;v++)check(Math.abs(unary.marginal[p][v]-actual.p[p][v])<1e-10,"zero factors did not reduce to exact unary head");}
        }
        FamilyF01KernelR26 full=new FamilyF01KernelR26(3,true),cut=new FamilyF01KernelR26(3,false);
        for(int trial=0;trial<3000;trial++){int[] input=permutation(10,random),target=new int[10];for(int p=0;p<10;p++)target[p]=input[(p+1)%10];for(FamilyF01KernelR26 m:new FamilyF01KernelR26[]{full,cut}){m.resetTemporalContext();m.observeOnly(input);loss(m,target);m.update(target);}}
        double fullLoss=0,cutLoss=0;for(int trial=0;trial<250;trial++){int[] input=permutation(10,random),target=new int[10];for(int p=0;p<10;p++)target[p]=input[(p+1)%10];full.resetTemporalContext();cut.resetTemporalContext();full.observeOnly(input);cut.observeOnly(input);fullLoss+=loss(full,target);cutLoss+=loss(cut,target);}fullLoss/=250;cutLoss/=250;check(fullLoss<cutLoss-.05,"cross-position advantage survived removal: "+fullLoss+" / "+cutLoss);
        for(String family:new String[]{"F01","F02"}){ModelGenomeSU2 parent=FamilyRegistryR26.genome(family);List<StructuralProposalR26.Proposal> children=StructuralProposalR26.mechanismChildren(parent);check(children.size()==2,"missing typed mutation/ablation");check(children.get(0).category.equals("STRUCTURAL_CANDIDATE")&&!StructuralProposalR26.structure(parent).equals(StructuralProposalR26.structure(children.get(0).genome)),"edge mutation counted as parameter-only");check(StructuralProposalR26.control(children.get(1).genome)&&children.get(1).category.equals("MECHANISM_ABLATION"),"ablation counted as active family mechanism");
            ModelGenomeSU2.Member mutated=children.get(0).genome.members.get(0);OnlineModelsSU2.Model base=FamilyRegistryR26.build(family),variant=ModelReplaySU2.build(mutated.kind,mutated.params);double behavioral=0;for(int t=0;t<80;t++){int[] d=permutation(10,random);base.update(d);variant.update(d);float[][] original=new float[10][10],altered=new float[10][10];base.predict(original,new float[base.stateWidth()]);variant.predict(altered,new float[variant.stateWidth()]);for(int row=0;row<10;row++)for(int col=0;col<10;col++)behavioral+=Math.abs(original[row][col]-altered[row][col]);}check(behavioral>1e-5,"typed edge mutation did not change executed prediction");
            for(StructuralProposalR26.Proposal child:children){ModelGenomeSU2.Member member=child.genome.members.get(0);OnlineModelsSU2.Model a=ModelReplaySU2.build(member.kind,member.params),b=ModelReplaySU2.build(member.kind,member.params);for(int t=0;t<50;t++)a.update(permutation(10,random));byte[] state=save(a);b.read(new DataInputStream(new ByteArrayInputStream(state)));int[] next=permutation(10,random);check(Math.abs(loss(a,next)-loss(b,next))<1e-12,"variant restored different forecast");a.update(next);b.update(next);check(Arrays.equals(save(a),save(b)),"variant next update differs");try{FamilyRegistryR26.build(family).read(new DataInputStream(new ByteArrayInputStream(state)));throw new AssertionError("state accepted a changed graph");}catch(IOException expected){}}
        }
        for(String family:new String[]{"F01","F02"}){OnlineModelsSU2.Model original=FamilyRegistryR26.build(family);for(int t=0;t<24;t++)original.update(permutation(10,random));byte[] current=save(original),old=new byte[current.length-5];System.arraycopy(current,0,old,0,4);old[3]=1;System.arraycopy(current,9,old,4,current.length-9);OnlineModelsSU2.Model migrated=FamilyRegistryR26.build(family);migrated.read(new DataInputStream(new ByteArrayInputStream(old)));int[] next=permutation(10,random);check(Math.abs(loss(original,next)-loss(migrated,next))<1e-12,"prior default checkpoint lost forecast");original.update(next);migrated.update(next);check(Arrays.equals(save(original),save(migrated)),"prior default checkpoint lost weights or update");
            ModelGenomeSU2 control=StructuralProposalR26.mechanismChildren(FamilyRegistryR26.genome(family)).get(1).genome;check(StructuralProposalR26.mechanismChildren(control).get(1).category.equals("NO_OP"),"repeated control counted as a new mechanism");}
        System.out.println("R26_FAMILY_MECHANISM_PASS enumerated=3..5 crossPositionNll="+fullLoss+" cutNll="+cutLoss);
    }
}
